with session_summary as (select session_id, round(stddev(duration_sec), 2) as stddev_duration_sec, max(duration_sec) as max_duration_sec from web_events where session_id in (27, 33) group by session_id) select s.id, s.started_at, s.country, ss.stddev_duration_sec, ss.max_duration_sec from sessions s inner join session_summary ss on s.id = ss.session_id where ss.stddev_duration_sec >= 22 order by s.country desc, id asc limit 50;
